import{c as a,Q as t,j as l,m as n}from"./chunks/framework.DOi4mjdC.js";const D=JSON.parse('{"title":"ValueDepend","description":"","frontmatter":{},"headers":[{"level":1,"title":"ValueDepend","slug":"valuedepend"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"}],"relativePath":"api/Utils-API/原型注册与管理/OpParamDef/ValueDepend.md","filePath":"api/Utils-API/原型注册与管理/OpParamDef/ValueDepend.md"}'),p={name:"api/Utils-API/原型注册与管理/OpParamDef/ValueDepend.md"};function r(d,e,i,o,s,h){return t(),l("div",null,[...e[0]||(e[0]=[n(`<h1 id="valuedepend" tabindex="-1">ValueDepend <a class="header-anchor" href="#valuedepend" aria-label="Permalink to &quot;ValueDepend&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>标识该输入是否为“数据依赖输入”，数据依赖输入是指在Tiling/InferShape等函数实现时依赖该输入的具体数据。该输入数据为host侧数据，开发者在Tiling函数/InferShape函数中可以通过TilingContext类的/InferShapeContext类的获取这个输入数据。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpParamDef &amp;ValueDepend(Option value_depend)</span></span>
<span class="line"><span>OpParamDef &amp;ValueDepend(Option value_depend, DependScope scope)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>输入/输出</th><th>说明</th></tr></thead><tbody><tr><td>value_depend</td><td>输入</td><td>value_depend有以下两种取值： REQUIRED：表示算子的输入必须是Const类型。 在调用算子的SetCheckSupport时，会校验算子的输入是否是Const类型。若校验通过，则将此输入的值下发到算子；否则报错。 OPTIONAL：表示算子的输入可以是Const类型，也可以不是Const类型。如果输入是Const类型，则将输入的值下发到算子，否则不下发。</td></tr><tr><td>scope</td><td>输入</td><td>scope类型为枚举类型DependScope，支持的取值为： ALL：指在Tiling/InferShape等函数实现时都依赖该输入的具体数据，行为与调用单参数ValueDepend重载接口一致。TILING：指仅在Tiling时依赖Tensor的值，可以支持Tiling下沉。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>OpParamDef算子定义，OpParamDef请参考<a href="./OpParamDef.html">OpParamDef</a>。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>仅支持对算子输入配置，输入的<a href="./DataType.html">参数数据类型</a>可以配置为DT_FLOAT/DT_BOOL/DT_INT64/DT_UINT64/DT_INT32/DT_UINT32/DT_INT16/DT_UINT16/DT_INT8/DT_UINT8，且必须满足以下三种情况之一：</p><ol><li><p>输入的<a href="./DataType.html">参数数据类型</a>配置全为DT_FLOAT，对应生成的输出类型aclFloatArray（aclnn数据类型）。</p></li><li><p>输入的<a href="./DataType.html">参数数据类型</a>配置全为DT_BOOL，对应生成的输出类型aclBoolArray（aclnn数据类型）。</p></li><li><p>输入的<a href="./DataType.html">参数数据类型</a>配置全为整数类型，即DT_INT64/DT_UINT64/DT_INT32/DT_UINT32/DT_INT16/DT_UINT16/DT_INT8/DT_UINT8，对应生成的输出类型aclIntArray（aclnn数据类型）。当数据类型配置含有DT_INT64以外的数据类型时，需要增加一组DT_INT64对应的输入/输出数据类型组合。</p></li></ol>`,12)])])}const c=a(p,[["render",r]]);export{D as __pageData,c as default};
